                        formatter={(value: number) => [`${value} erledigt`, 'Gewohnheiten']}
                      />
                      <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                        {chartData.map((entry, index) => (
                          <Cell
                            key={index}
                            fill={entry.isToday ? 'hsl(158 45% 30%)' : 'hsl(158 45% 30% / 0.5)'}
                          />
