                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* ── CENTER COLUMN: Today's Habits ── */}
          <div className="space-y-6">
            <Card className="border shadow-none hover:shadow-sm transition-shadow">
              <CardHeader className="flex flex-row items-center justify-between pb-3">
